struct Header{unsigned short major,minor;u32 bytes;u64 replyHandle,requestId;};
struct CreateReq{Header h;i32 x,y;u32 width,height;}; struct CreateRep{Header h;u32 status,reserved;u64 windowHandle;};
struct EventHeader{unsigned short major,minor;u32 bytes;u64 windowHandle,sequence;}; struct KeyEv{EventHeader h;u32 codepoint,flags;}; struct PtrEv{EventHeader h;i32 x,y,dx,dy;u32 flags,reserved;}; struct CloseEv{EventHeader h;u32 reason,reserved;};
