static inline void fill(u32*p,u32 n,u32 c){for(u32 i=0;i<n;i++)p[i]=c;} static inline void rect(u32*p,u32 W,u32 H,i32 x,i32 y,i32 w,i32 h,u32 c){if(x<0){w+=x;x=0;}if(y<0){h+=y;y=0;}if(x+w>(i32)W)w=W-x;if(y+h>(i32)H)h=H-y;if(w<=0||h<=0)return;for(i32 yy=0;yy<h;yy++)for(i32 xx=0;xx<w;xx++)p[(y+yy)*W+x+xx]=c;}
static u8 glyph(char c,int r){if(c>='a'&&c<='z')c-=32;switch(c){case 'A':{u8 a[7]={14,17,17,31,17,17,17};return a[r];}case 'B':{u8 a[7]={30,17,17,30,17,17,30};return a[r];}case 'C':{u8 a[7]={14,17,16,16,16,17,14};return a[r];}case 'D':{u8 a[7]={30,17,17,17,17,17,30};return a[r];}case 'E':{u8 a[7]={31,16,16,30,16,16,31};return a[r];}case 'F':{u8 a[7]={31,16,16,30,16,16,16};return a[r];}case 'G':{u8 a[7]={14,17,16,23,17,17,15};return a[r];}case 'H':{u8 a[7]={17,17,17,31,17,17,17};return a[r];}case 'I':{u8 a[7]={31,4,4,4,4,4,31};return a[r];}case 'J':{u8 a[7]={7,2,2,2,18,18,12};return a[r];}case 'K':{u8 a[7]={17,18,20,24,20,18,17};return a[r];}case 'L':{u8 a[7]={16,16,16,16,16,16,31};return a[r];}case 'M':{u8 a[7]={17,27,21,21,17,17,17};return a[r];}case 'N':{u8 a[7]={17,25,21,19,17,17,17};return a[r];}case 'O':{u8 a[7]={14,17,17,17,17,17,14};return a[r];}case 'P':{u8 a[7]={30,17,17,30,16,16,16};return a[r];}case 'Q':{u8 a[7]={14,17,17,17,21,18,13};return a[r];}case 'R':{u8 a[7]={30,17,17,30,20,18,17};return a[r];}case 'S':{u8 a[7]={15,16,16,14,1,1,30};return a[r];}case 'T':{u8 a[7]={31,4,4,4,4,4,4};return a[r];}case 'U':{u8 a[7]={17,17,17,17,17,17,14};return a[r];}case 'V':{u8 a[7]={17,17,17,17,17,10,4};return a[r];}case 'W':{u8 a[7]={17,17,17,21,21,21,10};return a[r];}case 'X':{u8 a[7]={17,17,10,4,10,17,17};return a[r];}case 'Y':{u8 a[7]={17,17,10,4,4,4,4};return a[r];}case 'Z':{u8 a[7]={31,1,2,4,8,16,31};return a[r];}
case '0':{u8 a[7]={14,17,19,21,25,17,14};return a[r];}case '1':{u8 a[7]={4,12,4,4,4,4,14};return a[r];}case '2':{u8 a[7]={14,17,1,2,4,8,31};return a[r];}case '3':{u8 a[7]={30,1,1,14,1,1,30};return a[r];}case '4':{u8 a[7]={2,6,10,18,31,2,2};return a[r];}case '5':{u8 a[7]={31,16,16,30,1,1,30};return a[r];}case '6':{u8 a[7]={14,16,16,30,17,17,14};return a[r];}case '7':{u8 a[7]={31,1,2,4,8,8,8};return a[r];}case '8':{u8 a[7]={14,17,17,14,17,17,14};return a[r];}case '9':{u8 a[7]={14,17,17,15,1,1,14};return a[r];}case '+':return r==3?31:(r==1||r==2||r==4||r==5?4:0);case '-':return r==3?31:0;case '=':return r==2||r==4?31:0;case '/':return (u8)(1<<(4-r*4/6));case '(':return r==0||r==6?2:(r==1||r==5?4:8);case ')':return r==0||r==6?8:(r==1||r==5?4:2);case '.':return r==6?4:0;case ':':return r==2||r==5?4:0;case '!':return r<5?4:(r==6?4:0);case '?':{u8 a[7]={14,17,1,2,4,0,4};return a[r];}default:return 0;}}
static inline void text(u32*p,u32 W,u32 H,i32 x,i32 y,const char*s,u32 c,int scale=1){for(;*s;s++,x+=6*scale){if(*s==' '){continue;}for(int r=0;r<7;r++){u8 bits=glyph(*s,r);for(int b=0;b<5;b++)if(bits&(1<<(4-b)))rect(p,W,H,x+b*scale,y+r*scale,scale,scale,c);}}}
static inline u64 makeWindow(u64&events,u32 w,u32 h,i32 x,i32 y){events=(u64)sc(SYS_IPC_CREATE,IPC_RECV);u64 desk=(u64)sc(SYS_SERVICE,DESKTOP);if(!events||!desk)return 0;CreateReq q{{1,1,sizeof(q),events,1},x,y,w,h};if(sc(SYS_IPC_SEND,desk,CREATE,(u64)&q,sizeof(q))<0)return 0;for(;;){Wire m{};i64 n=sc(SYS_IPC_RECV,events,(u64)&m);if(n>0&&m.type==CREATE_REPLY){auto*r=(CreateRep*)m.payload;return r->status?0:r->windowHandle;}sc(SYS_YIELD);}}
extern "C" inline void* memset(void*d,int v,unsigned long n){u8*p=(u8*)d;while(n--)*p++=(u8)v;return d;}
extern "C" inline void* memcpy(void*d,const void*s,unsigned long n){u8*a=(u8*)d;const u8*b=(const u8*)s;while(n--)*a++=*b++;return d;}
